    "pdfPage": 82,
    "hasFigureReference": false,
    "solutionVariants": [
      {
        "html": "<pre class=\"java\">\npublic static boolean contains3(List&lt;String&gt; list) {\n    Map&lt;String, Integer&gt; counts = new HashMap&lt;String, Integer&gt;();\n    for (String value : list) {\n        if (counts.containsKey(value)) {\n            int count = counts.get(value);\n            count++;\n            counts.put(value, count);\n            if (count &gt;= 3) {\n                return true;\n            }\n        } else {\n            counts.put(value, 1);\n        }\n    }\n    return false;\n}\n</pre>",
        "text": "public static boolean contains3(List<String> list) {\n    Map<String, Integer> counts = new HashMap<String, Integer>();\n    for (String value : list) {\n        if (counts.containsKey(value)) {\n            int count = counts.get(value);\n            count++;\n            counts.put(value, count);\n            if (count >= 3) {\n                return true;\n            }\n        } else {\n            counts.put(value, 1);\n        }\n    }\n    return false;\n}"
      }
    ],
    "solutionText": "public static boolean contains3(List<String> list) {\n    Map<String, Integer> counts = new HashMap<String, Integer>();\n    for (String value : list) {\n        if (counts.containsKey(value)) {\n            int count = counts.get(value);\n            count++;\n            counts.put(value, count);\n            if (count >= 3) {\n                return true;\n            }\n        } else {\n            counts.put(value, 1);\n        }\n    }\n    return false;\n}",
    "pdfPageRange": "80-84"
