    "id": "exercise-chapter-13-14",
    "number": 14,
    "displayNumber": "13.14",
    "title": "Exercise 13.14 · WordsBetween",
    "name": "WordsBetween",
    "chapterId": "chapter-13",
    "chapterNumber": 13,
    "chapter": "Chapter 13",
    "chapterTitle": "Searching and Sorting",
    "topic": "Searching & Sorting",
    "prompt": "Write code to read a dictionary from a file, then prompt the user for two\n     words and tell the user how many words in the dictionary fall between\n     those two words. Here is a sample run of the program:\n\n     Type two words:         goodbye hello\n     There are 4418 words between goodbye and hello\n\n     Use the binary search algorithm in your solution.",
    "pdfPage": 97,
    "hasFigureReference": false,
    "solutionVariants": [
      {
        "html": "<pre class=\"java\">\n// Searches for a word in a dictionary text file\n// and reports that word's position in the file.\nimport java.io.*;\nimport java.util.*;\npublic class WordsBetween {\n    public static void main(String[] args) throws FileNotFoundException {\n        // read sorted dictionary file into an ArrayList\n        Scanner in = new Scanner(new File(\"words.txt\"));\n        ArrayList&lt;String&gt; words = new ArrayList&lt;String&gt;();\n        while (in.hasNext()) {\n            String word = in.next();\n            words.add(word);\n        }\n        \n        // binary search the list for a particular word\n        System.out.print(\"Type two words: \");\n        Scanner console = new Scanner(System.in);\n        String word1 = console.next();\n        String word2 = console.next();\n        \n        int index1 = Collections.binarySearch(words, word1);\n        int index2 = Collections.binarySearch(words, word2);\n        if (index1 &gt;= 0 &amp;&amp; index2 &gt;= 0) {\n            int between = Math.min(Math.abs(index2 - index1) - 1, 0);\n            System.out.println(\"There are \" + between + \" words between \"\n            \t\t+ word1 + \" and \" + word2);\n        } else {\n            System.out.println(word1 + \" or \" + word2 + \" is not found\");\n        }\n    }\n}\n</pre>",
        "text": "// Searches for a word in a dictionary text file\n// and reports that word's position in the file.\nimport java.io.*;\nimport java.util.*;\npublic class WordsBetween {\n    public static void main(String[] args) throws FileNotFoundException {\n        // read sorted dictionary file into an ArrayList\n        Scanner in = new Scanner(new File(\"words.txt\"));\n        ArrayList<String> words = new ArrayList<String>();\n        while (in.hasNext()) {\n            String word = in.next();\n            words.add(word);\n        }\n\n        // binary search the list for a particular word\n        System.out.print(\"Type two words: \");\n        Scanner console = new Scanner(System.in);\n        String word1 = console.next();\n        String word2 = console.next();\n\n        int index1 = Collections.binarySearch(words, word1);\n        int index2 = Collections.binarySearch(words, word2);\n        if (index1 >= 0 && index2 >= 0) {\n            int between = Math.min(Math.abs(index2 - index1) - 1, 0);\n            System.out.println(\"There are \" + between + \" words between \"\n            \t\t+ word1 + \" and \" + word2);\n        } else {\n            System.out.println(word1 + \" or \" + word2 + \" is not found\");\n        }\n    }\n}"
      }
    ],
    "solutionText": "// Searches for a word in a dictionary text file\n// and reports that word's position in the file.\nimport java.io.*;\nimport java.util.*;\npublic class WordsBetween {\n    public static void main(String[] args) throws FileNotFoundException {\n        // read sorted dictionary file into an ArrayList\n        Scanner in = new Scanner(new File(\"words.txt\"));\n        ArrayList<String> words = new ArrayList<String>();\n        while (in.hasNext()) {\n            String word = in.next();\n            words.add(word);\n        }\n\n        // binary search the list for a particular word\n        System.out.print(\"Type two words: \");\n        Scanner console = new Scanner(System.in);\n        String word1 = console.next();\n        String word2 = console.next();\n\n        int index1 = Collections.binarySearch(words, word1);\n        int index2 = Collections.binarySearch(words, word2);\n        if (index1 >= 0 && index2 >= 0) {\n            int between = Math.min(Math.abs(index2 - index1) - 1, 0);\n            System.out.println(\"There are \" + between + \" words between \"\n            \t\t+ word1 + \" and \" + word2);\n        } else {\n            System.out.println(word1 + \" or \" + word2 + \" is not found\");\n        }\n    }\n}",
    "pdfPageRange": "94-98"
