    "id": "exercise-chapter-13-17",
    "number": 17,
    "displayNumber": "13.17",
    "title": "Exercise 13.17 · CityComparator",
    "name": "CityComparator",
    "chapterId": "chapter-13",
    "chapterNumber": 13,
    "chapter": "Chapter 13",
    "chapterTitle": "Searching and Sorting",
    "topic": "Searching & Sorting",
    "prompt": "Write a Comparator that compares String objects of a particular format.\n     Each string is of a form such as \"123456 Seattle, WA\", beginning with\n     a numeric token that is followed by additional text tokens. Your job is to\n     treat the first tokens as integers and compare them in numerical order.\n     You cannot simply compare them by using the strings' compareTo\n     method, since it would treat the numbers as text and not as integers. For\n     example, \"276453 Helena, MT\" is greater than \"9847 New York, NY\".\n     Use a Scanner to tokenize the strings while comparing them.",
    "pdfPage": 97,
    "hasFigureReference": false,
    "solutionVariants": [
      {
        "html": "<pre class=\"java\">\n// Compares Strings in a particular format.\n// Example: \"123456 Seattle, WA\", beginning with a numeric token that is followed by additional text tokens\n// Example, \"276453 Helena, MT\" is greater than \"9847 New York, NY\".\nimport java.util.*;\npublic class CityComparator implements Comparator&lt;String&gt; {\n    public int compare(String s1, String s2) {\n        Scanner scan1 = new Scanner(s1);\n        Scanner scan2 = new Scanner(s2);\n        int code1 = scan1.nextInt();\n        int code2 = scan2.nextInt();\n        if (code1 != code2) {\n            return code1 - code2;\n        }\n        \n        String city1 = scan1.next().replace(\",\", \"\");\n        String city2 = scan2.next().replace(\",\", \"\");\n        if (!city1.equals(city2)) {\n            return city1.compareTo(city2);\n        }\n        \n        String state1 = scan1.next();\n        String state2 = scan2.next();\n        return state1.compareTo(state2);\n    }\n}\n</pre>",
        "text": "// Compares Strings in a particular format.\n// Example: \"123456 Seattle, WA\", beginning with a numeric token that is followed by additional text tokens\n// Example, \"276453 Helena, MT\" is greater than \"9847 New York, NY\".\nimport java.util.*;\npublic class CityComparator implements Comparator<String> {\n    public int compare(String s1, String s2) {\n        Scanner scan1 = new Scanner(s1);\n        Scanner scan2 = new Scanner(s2);\n        int code1 = scan1.nextInt();\n        int code2 = scan2.nextInt();\n        if (code1 != code2) {\n            return code1 - code2;\n        }\n\n        String city1 = scan1.next().replace(\",\", \"\");\n        String city2 = scan2.next().replace(\",\", \"\");\n        if (!city1.equals(city2)) {\n            return city1.compareTo(city2);\n        }\n\n        String state1 = scan1.next();\n        String state2 = scan2.next();\n        return state1.compareTo(state2);\n    }\n}"
      }
    ],
    "solutionText": "// Compares Strings in a particular format.\n// Example: \"123456 Seattle, WA\", beginning with a numeric token that is followed by additional text tokens\n// Example, \"276453 Helena, MT\" is greater than \"9847 New York, NY\".\nimport java.util.*;\npublic class CityComparator implements Comparator<String> {\n    public int compare(String s1, String s2) {\n        Scanner scan1 = new Scanner(s1);\n        Scanner scan2 = new Scanner(s2);\n        int code1 = scan1.nextInt();\n        int code2 = scan2.nextInt();\n        if (code1 != code2) {\n            return code1 - code2;\n        }\n\n        String city1 = scan1.next().replace(\",\", \"\");\n        String city2 = scan2.next().replace(\",\", \"\");\n        if (!city1.equals(city2)) {\n            return city1.compareTo(city2);\n        }\n\n        String state1 = scan1.next();\n        String state2 = scan2.next();\n        return state1.compareTo(state2);\n    }\n}",
