        "html": "<pre class=\"java\">\n// Places the elements of the given array into sorted order\n// using the selection sort algorithm.\n// post: array is in sorted (nondecreasing) order\npublic static void dualSelectionSort(int[] a) {\n    for (int i = 0; i &lt; a.length / 2; i++) {\n        // find index of smallest/largest element\n        int smallest = i;\n        int largest = i;\n        for (int j = i + 1; j &lt; a.length - i; j++) {\n            if (a[j] &lt; a[smallest]) {\n                smallest = j;\n            } else if (a[j] &gt; a[largest]) {\n                largest = j;\n            }\n        }\n        \n        int temp = a[i];       // swap smallest to front\n        a[i] = a[smallest];\n        a[smallest] = temp;\n        if (largest == i) {\n            largest = smallest;\n        }\n        \n        int temp2 = a[length - 1 - i];       // swap largest to end\n        a[length - 1 - i] = a[largest];\n        a[largest] = temp2;\n    }\n}\n</pre>",
        "text": "// Places the elements of the given array into sorted order\n// using the selection sort algorithm.\n// post: array is in sorted (nondecreasing) order\npublic static void dualSelectionSort(int[] a) {\n    for (int i = 0; i < a.length / 2; i++) {\n        // find index of smallest/largest element\n        int smallest = i;\n        int largest = i;\n        for (int j = i + 1; j < a.length - i; j++) {\n            if (a[j] < a[smallest]) {\n                smallest = j;\n            } else if (a[j] > a[largest]) {\n                largest = j;\n            }\n        }\n\n        int temp = a[i];       // swap smallest to front\n        a[i] = a[smallest];\n        a[smallest] = temp;\n        if (largest == i) {\n            largest = smallest;\n        }\n\n        int temp2 = a[length - 1 - i];       // swap largest to end\n        a[length - 1 - i] = a[largest];\n        a[largest] = temp2;\n    }\n}"
