        "html": "<pre class=\"java\">\npublic Stack&lt;Integer&gt; copyStack(Stack&lt;Integer&gt; s) {\n    Stack&lt;Integer&gt; s2 = new Stack&lt;Integer&gt;();\n    Queue&lt;Integer&gt; q = new LinkedList&lt;Integer&gt;();\n    while (!s.isEmpty()) {\n        s2.push(s.pop());\n    }\n    while(!s2.isEmpty()) {\n        q.add(s2.pop());\n    }\n    while (!q.isEmpty()) {\n        int n = q.remove();\n        s.push(n);\n        s2.push(n);\n    }\n    return s2;\n}\n</pre>",
