        "html": "<pre class=\"java\">\npublic boolean equals(Stack&lt;Integer&gt; s1, Stack&lt;Integer&gt; s2) {\n    Stack&lt;Integer&gt; s3 = new Stack&lt;Integer&gt;();\n    boolean same = true;\n    while (same &amp;&amp; !s1.isEmpty() &amp;&amp; !s2.isEmpty()) {\n        int num1 = s1.pop();\n        int num2 = s2.pop();\n        if (num1 != num2) {\n            same = false;\n        }\n        s3.push(num1);\n        s3.push(num2);\n    }\n    same = same &amp;&amp; s1.isEmpty() &amp;&amp; s2.isEmpty();\n    while (!s3.isEmpty()) {\n        s2.push(s3.pop());\n        s1.push(s3.pop());\n    }\n    return same;\n}\n</pre>",
