        "text": "public void split() {\n    if (front != null) {\n        ListNode current = front;\n        while (current.next != null) {\n            if (current.next.data < 0) {\n                ListNode temp = current.next;\n                current.next = current.next.next;\n                temp.next = front;\n                front = temp;\n            } else {\n                current = current.next;\n            }\n        }\n    }\n}"
