        "html": "<pre class=\"java\">\npublic void removeRange(int low, int high) {\n    if (low &lt; 0 || high &lt; 0) {\n        throw new IllegalArgumentException();\n    }\n    if (low == 0) {\n        while (high &gt;= 0) {\n            front = front.next;\n            high--;\n        }\n    } else {\n        ListNode current = front;\n        int count = 1;\n        while (count &lt; low) {\n            current = current.next;\n            count++;\n        }\n        ListNode current2 = current.next;\n        while (count &lt; high) {\n            current2 = current2.next;\n            count++;\n        }\n        current.next = current2.next;\n    }\n}\n</pre>",
